import{_ as i,c as a,o as t,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"Designating English as the Official Language of The United States","description":"","frontmatter":{"title":"Designating English as the Official Language of The United States","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/designating-english-as-the-official-language-of-the-united-states/","publishDate":"2025-03-01"},"headers":[],"relativePath":"executive-orders/2025-03-01-designating-english-as-the-official-language-of-the-united-states.md","filePath":"executive-orders/2025-03-01-designating-english-as-the-official-language-of-the-united-states.md"}'),s={name:"executive-orders/2025-03-01-designating-english-as-the-official-language-of-the-united-states.md"};function o(l,e,r,g,h,c){return t(),a("div",null,e[0]||(e[0]=[n('<h1 id="designating-english-as-the-official-language-of-the-united-states" tabindex="-1">Designating English as the Official Language of The United States <a class="header-anchor" href="#designating-english-as-the-official-language-of-the-united-states" aria-label="Permalink to &quot;Designating English as the Official Language of The United States&quot;">​</a></h1><p>Published: Saturday, March 1, 2025</p><h2 id="summary-of-executive-order-on-english-as-the-official-language" tabindex="-1">Summary of Executive Order on English as the Official Language <a class="header-anchor" href="#summary-of-executive-order-on-english-as-the-official-language" aria-label="Permalink to &quot;Summary of Executive Order on English as the Official Language&quot;">​</a></h2><h3 id="purpose-and-policy" tabindex="-1"><strong>Purpose and Policy</strong> <a class="header-anchor" href="#purpose-and-policy" aria-label="Permalink to &quot;**Purpose and Policy**&quot;">​</a></h3><ul><li>English has historically been the national language of the United States.</li><li>Foundational documents, including the Declaration of Independence and the Constitution, were written in English.</li><li>Declaring English as the official language promotes unity, cultural cohesion, and efficient governance.</li><li>Encouraging new Americans to learn English fosters economic opportunities, community engagement, and civic participation.</li><li>Establishing a single official language streamlines communication and reinforces shared national values.</li></ul><h3 id="definitions" tabindex="-1"><strong>Definitions</strong> <a class="header-anchor" href="#definitions" aria-label="Permalink to &quot;**Definitions**&quot;">​</a></h3><ul><li><strong>Agency</strong>: As defined in <strong>44 U.S.C. § 3502</strong>, excluding the Executive Office of the President.</li><li><strong>Agency Head</strong>: The highest-ranking official of an agency (e.g., Secretary, Administrator, Chairman, or Director).</li></ul><h3 id="designation-of-english-as-the-official-language" tabindex="-1"><strong>Designation of English as the Official Language</strong> <a class="header-anchor" href="#designation-of-english-as-the-official-language" aria-label="Permalink to &quot;**Designation of English as the Official Language**&quot;">​</a></h3><ul><li>English is officially designated as the <strong>sole</strong> language of the United States.</li><li><strong>Revokes</strong> Executive Order 13166 (Improving Access to Services for Persons with Limited English Proficiency).</li><li>Agencies are <strong>not required</strong> to eliminate multilingual services but may decide how best to fulfill their mission.</li><li>The Attorney General must rescind guidance issued under Executive Order 13166 and provide updates consistent with the law.</li></ul><h3 id="general-provisions" tabindex="-1"><strong>General Provisions</strong> <a class="header-anchor" href="#general-provisions" aria-label="Permalink to &quot;**General Provisions**&quot;">​</a></h3><ul><li>This order does <strong>not</strong> override existing legal authorities of agencies.</li><li>Implementation must comply with <strong>applicable laws</strong> and <strong>budget availability</strong>.</li><li>The order does <strong>not</strong> create any enforceable legal rights for individuals.</li></ul><p><strong>Issued: March 1, 2025 – The White House</strong></p><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/designating-english-as-the-official-language-of-the-united-states/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/designating-english-as-the-official-language-of-the-united-states/</a></p>',13)]))}const f=i(s,[["render",o]]);export{u as __pageData,f as default};
